client.Manager.Logic.AddPendingAction(t =>
            {
                if (client.Player.Owner == null) return;
                SellableObject obj = client.Player.Owner.GetEntity(packet.ObjectId) as SellableObject;
                if (obj != null)
                    obj.Buy(client.Player);
            }, PendingPriority.Networking);

client.Manager.Logic.AddPendingAction(t =>
            {
                using (Database db = new Database())
                {
                    db.ReadStats(client.Account);
                    client.Player.Credits = client.Account.Credits;
                    client.Player.UpdateCount++;
                }
            }, PendingPriority.Networking);

string[] bannednames = { "Dick", "Fuck", "Pussy", "Cunt", "Bitch", "Nigger", "Nigga", "Niqqa", "Cunt", "Shit", "Penis", "Vagina", "Chent", "Niqqer", "Negro", "Ngr", "Chink", "Fag", "Faggot", "Fgt", "Fagot", "Fagit", "Ass", "Autistic", "Autism", "Schlong", "vag", "damn", "tits", "tlts", "retard", "asd", "Kalle", "Kaile", "Kalie", "xDalla", "xDalia", "xDaila", "McFarvo", "Pixl", "TheHangman", "White", "DrMini", "TEEBQNE", "TBQNEE", "FloFlorian", "Lore", "Dalla", "Daila", "Dalia", "Clocking", "Ciocking", "IArkani", "lArkani", "BunnyBomb", "Liinkii", "Gamingland", "GamingIand", "TheRegal", "TheRegaI", "ParagonX", "Cantplay", "Billyhendr", "Nilly", "Trapped", "Botmaker", "JustANoob", "JustANoobROTMG", "Niiiy", "niily", "niliy", "Lucifer", "Kithio", "Case", "Travoos", "XD", "DX", "Trol", "Troll", "lol", "lel", "OMG", "suck" };

            foreach (string i in bannednames)
            {
                if (i.ToLower().Equals(packet.Name) || packet.Name.ToLower().Contains(i.ToLower()))
                {
                    client.SendPacket(new NameResultPacket
                    {
                        Success = false,
                        ErrorText = "Error.nameAlreadyInUse"
                    });
                    return;
                }
            }

            using (Database db = new Database())
            {
                MySqlCommand cmdx = db.CreateQuery();
                cmdx.CommandText = "SELECT namechosen FROM accounts WHERE id=@accId";
                cmdx.Parameters.AddWithValue("@accId", client.Account.AccountId);
                object execx = cmdx.ExecuteScalar();
                bool namechosen = bool.Parse(execx.ToString());
                if (String.IsNullOrEmpty(packet.Name) || packet.Name.Length > 10)
                {
                    client.SendPacket(new NameResultPacket
                    {
                        Success = false,
                        ErrorText = "Error.nameIsNotAlpha"
                    });
                }
                else
                {
                    MySqlCommand cmd = db.CreateQuery();
                    cmd.CommandText = "SELECT COUNT(name) FROM accounts WHERE name=@name;";
                    cmd.Parameters.AddWithValue("@name", packet.Name);
                    object x = cmd.ExecuteScalar();
                    if (int.Parse(x.ToString()) > 0)
                    {
                        client.SendPacket(new NameResultPacket
                        {
                            Success = false,
                            ErrorText = "Error.nameAlreadyInUse"
                        });
                    }
                    else
                    {
                        db.ReadStats(client.Account);
                        if (client.Account.Credits < 1000 && namechosen)
                            client.SendPacket(new NameResultPacket
                            {
                                Success = false,
                                ErrorText = "server.not_enough_gold"
                            });
                        else
                        {
                            if (client.Account.NameChosen == false)
                            {
                                cmd = db.CreateQuery();
                                cmd.CommandText = "UPDATE accounts SET name=@name, namechosen=TRUE WHERE id=@accId;";
                                cmd.Parameters.AddWithValue("@accId", client.Account.AccountId);
                                cmd.Parameters.AddWithValue("@name", packet.Name);
                                if (cmd.ExecuteNonQuery() > 0)
                                {
                                    client.Player.Name = packet.Name;
                                    client.Player.NameChosen = true;
                                    client.Player.UpdateCount++;
                                    client.SendPacket(new NameResultPacket
                                    {
                                        Success = true,
                                        ErrorText = "server.buy_success"
                                    });
                                }
                                else
                                {
                                    client.SendPacket(new NameResultPacket
                                    {
                                        Success = false,
                                        ErrorText = "GuildChronicle.left"
                                    });
                                }
                            }
                            else
                            {
                                cmd = db.CreateQuery();
                                cmd.CommandText = "UPDATE accounts SET name=@name, namechosen=TRUE WHERE id=@accId;";
                                cmd.Parameters.AddWithValue("@accId", client.Account.AccountId);
                                cmd.Parameters.AddWithValue("@name", packet.Name);
                                if (cmd.ExecuteNonQuery() > 0)
                                {
                                    client.Player.Credits = db.UpdateCredit(client.Account, -1000);
                                    client.Player.Name = packet.Name;
                                    client.Player.NameChosen = true;
                                    client.Player.UpdateCount++;
                                    client.SendPacket(new NameResultPacket
                                    {
                                        Success = true,
                                        ErrorText = "server.buy_success"
                                    });
                                }
                                else
                                {
                                    client.SendPacket(new NameResultPacket
                                    {
                                        Success = false,
                                        ErrorText = "GuildChronicle.left"
                                    });
                                }
                            }
                        }
                    }
                }
            }

using (Database dbx = new Database())
            {
                MySqlCommand cmd = dbx.CreateQuery();
                int nextCharId = 1;
                if (!client.Account.IsGuestAccount)
                {
                    nextCharId = dbx.GetNextCharId(client.Account);

                    cmd.CommandText = "SELECT maxCharSlot FROM accounts WHERE id=@accId;";
                    cmd.Parameters.AddWithValue("@accId", client.Account.AccountId);
                    int maxChar = (int) cmd.ExecuteScalar();

                    cmd = dbx.CreateQuery();
                    cmd.CommandText = "SELECT COUNT(id) FROM characters WHERE accId=@accId AND dead = FALSE;";
                    cmd.Parameters.AddWithValue("@accId", client.Account.AccountId);
                    int currChar = (int) (long) cmd.ExecuteScalar();

                    if (currChar >= maxChar)
                    {
                        client.Disconnect();
                        return;
                    }
                }
                client.Character = Database.CreateCharacter(client.Manager.GameData, (ushort) packet.ClassType,
                    nextCharId);

                int[] stats = new[]
                {
                    client.Character.MaxHitPoints,
                    client.Character.MaxMagicPoints,
                    client.Character.Attack,
                    client.Character.Defense,
                    client.Character.Speed,
                    client.Character.Dexterity,
                    client.Character.HpRegen,
                    client.Character.MpRegen
                };

                int skin = client.Account.OwnedSkins.Contains(packet.SkinType) ? packet.SkinType : 0;
                client.Character.Skin = skin;
                cmd = dbx.CreateQuery();
                cmd.Parameters.AddWithValue("@accId", client.Account.AccountId);
                cmd.Parameters.AddWithValue("@charId", nextCharId);
                cmd.Parameters.AddWithValue("@charType", packet.ClassType);
                cmd.Parameters.AddWithValue("@items", Utils.GetCommaSepString(client.Character.EquipSlots()));
                cmd.Parameters.AddWithValue("@stats", Utils.GetCommaSepString(stats));
                cmd.Parameters.AddWithValue("@fameStats", client.Character.FameStats.ToString());
                cmd.Parameters.AddWithValue("@skin", skin);
                cmd.CommandText =
                    "INSERT INTO characters (accId, charId, charType, level, exp, fame, items, hp, mp, stats, dead, pet, fameStats, skin) VALUES (@accId, @charId, @charType, 1, 0, 0, @items, 100, 100, @stats, FALSE, -1, @fameStats, @skin);";

                if (cmd.ExecuteNonQuery() > 0)
                {
                    World target = client.Manager.Worlds[client.TargetWorld];
                    client.SendPacket(new Create_SuccessPacket
                    {
                        CharacterID = client.Character.CharacterId,
                        ObjectID =
                            client.Manager.Worlds[client.TargetWorld].EnterWorld(
                                client.Player = new Player(client.Manager, client))
                    });
                    client.Stage = ProtocalStage.Ready;
                }
                else
                {
                    client.SendPacket(new FailurePacket
                    {
                        ErrorDescription = "Failed to Load character."
                    });
                }
            }

Player target;
            if(client.Player.Owner == null) return;
            client.Manager.Logic.AddPendingAction(t =>
            {
                using (Database db = new Database())
                {
                    target = client.Player.Owner.GetEntity(packet.ObjectId) is Player ? client.Player.Owner.GetEntity(packet.ObjectId) as Player : null;
                    if (target == null) return;
                    if(client.Account.AccountId == target.AccountId)
                    {
                        SendFailure("You cannot do that with yourself.");
                        return;
                    }
                    switch (packet.AccountListId)
                    {
                        case AccountListPacket.LOCKED_LIST_ID:
                            if (packet.Add)
                            {
                                db.AddLock(client.Account.AccountId, target.AccountId);
                                client.Player.Locked.Add(target.AccountId);
                            }
                            else
                            {
                                db.RemoveLock(client.Account.AccountId, target.AccountId);
                                client.Player.Locked.Remove(target.AccountId);
                            }
                            break;
                        case AccountListPacket.IGNORED_LIST_ID:
                            if (packet.Add)
                            {
                                db.AddIgnore(client.Account.AccountId, target.AccountId);
                                client.Player.Ignored.Add(target.AccountId);
                            }
                            else
                            {
                                db.RemoveIgnore(client.Account.AccountId, target.AccountId);
                                client.Player.Ignored.Remove(target.AccountId);
                            }
                            break;
                    }

                    //List<string> list;
                    //if (packet.AccountListId == LOCKED_LIST_ID)
                    //    list = client.Player.Locked;
                    //else if (packet.AccountListId == IGNORED_LIST_ID)
                    //    list = client.Player.Ignored;
                    //else return;
                    //if (list == null)
                    //    list = new List<string>();
                    //Player player = client.Player.Owner.GetEntity(packet.ObjectId) as Player;
                    //if (player == null) return;
                    //int accId = client.Account.AccountId;
                    //if (packet.Add && list.Count < 6)
                    //    list.Add(accId.ToString());
                    //else
                    //    list.Remove(accId.ToString());

                    //if (packet.Add)
                    //{
                    //    list.Add(accId.ToString());
                    //    if (packet.AccountListId == LOCKED_LIST_ID)
                    //        db.AddLock(client.Account.AccountId, accId);
                    //    if (packet.AccountListId == IGNORED_LIST_ID)
                    //        db.AddIgnore(client.Account.AccountId, accId);
                    //}
                    //else
                    //{
                    //    list.Remove(accId.ToString());
                    //    if (packet.AccountListId == LOCKED_LIST_ID)
                    //        db.RemoveLock(client.Account.AccountId, accId);
                    //    if (packet.AccountListId == IGNORED_LIST_ID)
                    //        db.RemoveIgnore(client.Account.AccountId, accId);
                    //}

                    //client.Player.SendAccountList(list, packet.AccountListId);
                }
            }, PendingPriority.Networking);

if (client.Player.Owner == null) return;

            client.Manager.Logic.AddPendingAction(t =>
            {
                Entity entity = client.Player.Owner.GetEntity(packet.TargetId);
                if (entity != null) //Tolerance
                {
                    Projectile prj = (client.Player as IProjectileOwner).Projectiles[packet.BulletId];
                    if (prj != null)
                        prj.ForceHit(entity, t);
                }
            }, PendingPriority.Networking);

using (Database db = new Database())
            {
                if (packet.Currency == 1)
                {
                    client.Player.CurrentFame = client.Account.Stats.Fame = db.UpdateFame(client.Account, -500);
                    client.Player.UpdateCount++;
                }
                else
                {
                    client.Player.Credits = client.Account.Credits = db.UpdateCredit(client.Account, -50);
                    client.SendPacket(new BuyResultPacket
                    {
                        Result = 0,
                        Message = "{server.buy_success}"
                    });
                    client.Player.UpdateCount++;
                }
            }
            client.Save();

            World world = client.Player.Manager.AddWorld(new Arena());

            client.Reconnect(new ReconnectPacket
            {
                Host = "",
                Port = Program.Settings.GetValue<int>("port"),
                GameId = world.Id,
                Name = world.Name,
                Key = Empty<byte>.Array,
            });

if (client.Player.Owner == null) return;
            World world = client.Manager.GetWorld(client.Player.Owner.Id);
            if (world.Id == World.NEXUS_ID)
            {
                client.SendPacket(new TextPacket
                {
                    Stars = -1,
                    BubbleTime = 0,
                    Name = "",
                    Text = "server.already_nexus"
                });
                return;
            }
            client.Reconnect(new ReconnectPacket
            {
                Host = "",
                Port = Program.Settings.GetValue<int>("port"),
                GameId = World.NEXUS_ID,
                Name = "nexus.Nexus",
                Key = Empty<byte>.Array,
            });

client.Manager.Logic.AddPendingAction(t =>
            {
                if (client.Player.HasConditionEffect(ConditionEffectIndex.Paused) ||
                    client.Player.HasConditionEffect(ConditionEffectIndex.Invincible))
                    return;

                try
                {
                    if (client.Player.Owner == null) return;
                    WmapTile tile = client.Player.Owner.Map[(int)packet.Position.X, (int)packet.Position.Y];
                    ObjectDesc objDesc = tile.ObjType == 0 ? null : client.Manager.GameData.ObjectDescs[tile.ObjType];
                    TileDesc tileDesc = client.Manager.GameData.Tiles[tile.TileId];
                    if (tileDesc.Damaging && (objDesc == null || !objDesc.ProtectFromGroundDamage))
                    {
                        int dmg = (int)client.Player.StatsManager.Random.obf6((uint)tileDesc.MinDamage, (uint)tileDesc.MaxDamage);
                        dmg = (int) client.Player.StatsManager.GetDefenseDamage(dmg, true);

                        client.Player.HP -= dmg;
                        client.Player.UpdateCount++;
                        if (client.Player.HP <= 0)
                            client.Player.Death(tileDesc.ObjectId);
                    }
                }
                catch (Exception ex)
                {
                    log.Error(ex);
                }
            }, PendingPriority.Networking);

if (Client.SERVER_VERSION != packet.BuildVersion)
            {
                client.SendPacket(new FailurePacket
                {
                    ErrorId = 0,
                    ErrorDescription = "server.update_client"
                });
                client.SendPacket(new FailurePacket
                {
                    ErrorId = 4,
                    ErrorDescription = Client.SERVER_VERSION
                });
                client.Disconnect();
                return;
            }
            client.Manager.Database.DoActionAsync(db =>
            {
                if ((client.Account = db.Verify(packet.GUID, packet.Password, Manager.GameData)) == null)
                {
                    log.Info(@"Account not verified.");
                    client.Account = Database.CreateGuestAccount(packet.GUID);

                    if (client.Account == null)
                    {
                        log.Info(@"Account is null!");
                        client.SendPacket(new FailurePacket
                        {
                            ErrorDescription = "Invalid account."
                        });
                        client.Disconnect();
                        return;
                    }
                }
                if (!client.Account.IsGuestAccount)
                {
                    int? timeout = null;

                    if (DateTime.Now <= Program.WhiteListTurnOff)
                    {
                        if (!IsWhiteListed(client.Account.Rank))
                        {
                            client.SendPacket(new FailurePacket
                            {
                                ErrorId = 0,
                                ErrorDescription = "You are not whitelisted!"
                            });
                            client.Disconnect();
                            return;
                        }
                    }
                    if (db.CheckAccountInUse(client.Account, ref timeout))
                    {
                        if (timeout == null)
                        {
                            client.SendPacket(new FailurePacket
                            {
                                ErrorId = 0,
                                ErrorDescription = "Account in use."
                            });
                        }
                        else
                        {
                            client.SendPacket(new FailurePacket
                            {
                                ErrorId = 0,
                                ErrorDescription = "Account in use. (" + timeout + " seconds until timeout.)"
                            });
                        }
                        client.Disconnect();
                        return;
                    }
                }
                log.Info(@"Client trying to connect!");
                client.ConnectedBuild = packet.BuildVersion;
                if (!client.Manager.TryConnect(client))
                {
                    client.Account = null;
                    client.SendPacket(new FailurePacket
                    {
                        ErrorDescription = "Failed to connect."
                    });
                    client.Disconnect();
                    log.Warn(@"Failed to connect.");
                }
                else
                {
                    log.Info(@"Client loading world");
                    if (packet.GameId == World.NEXUS_LIMBO) packet.GameId = World.NEXUS_ID;
                    World world = client.Manager.GetWorld(packet.GameId);
                    if (world == null && packet.GameId == World.TUT_ID) world = client.Manager.AddWorld(new Tutorial(false));
                    if (world == null)
                    {
                        client.SendPacket(new FailurePacket
                        {
                            ErrorId = 1,
                            ErrorDescription = "Invalid world."
                        });
                        client.Disconnect();
                        return;
                    }
                    if (world.NeedsPortalKey)
                    {
                        if (!world.PortalKey.SequenceEqual(packet.Key))
                        {
                            client.SendPacket(new FailurePacket
                            {
                                ErrorId = 1,
                                ErrorDescription = "Invalid Portal Key"
                            });
                            client.Disconnect();
                            return;
                        }
                        if (world.PortalKeyExpired)
                        {
                            client.SendPacket(new FailurePacket
                            {
                                ErrorId = 1,
                                ErrorDescription = "Portal key expired."
                            });
                            client.Disconnect();
                            return;
                        }
                    }
                    log.Info(@"Client joined world " + world.Id);
                    if (packet.MapInfo.Length > 0) //Test World
                        (world as Test).LoadJson(Encoding.Default.GetString(packet.MapInfo));

                    if (world.IsLimbo)
                        world = world.GetInstance(client);
                    client.Random = new wRandom(world.Seed);
                    client.TargetWorld = world.Id;
                    client.SendPacket(new MapInfoPacket
                    {
                        Width = world.Map.Width,
                        Height = world.Map.Height,
                        Name = world.Name,
                        Seed = world.Seed,
                        ClientWorldName = world.ClientWorldName,
                        Difficulty = world.Difficulty,
                        Background = world.Background,
                        AllowTeleport = world.AllowTeleport,
                        ShowDisplays = world.ShowDisplays,
                        ClientXML = world.ClientXml,
                        ExtraXML = Manager.GameData.AdditionXml
                    });
                    client.Stage = ProtocalStage.Handshaked;
                }
            });

if (client.Player.Owner == null) return;

            if (client.Player.Owner is PetYard)
            {
                client.SendPacket(new InvResultPacket
                {
                    Result = 0
                });
            }

            client.Manager.Logic.AddPendingAction(t =>
            {
                //TODO: locker again
                const ushort NORM_BAG = 0x0500;
                const ushort SOUL_BAG = 0x0507;

                Entity entity = client.Player.Owner.GetEntity(packet.SlotObject.ObjectId);
                IContainer con = entity as IContainer;
                Item item = null;
                if (packet.SlotObject.SlotId == 254)
                {
                    client.Player.HealthPotions--;
                    item = client.Player.Manager.GameData.Items[0xa22];
                }
                else if (packet.SlotObject.SlotId == 255)
                {
                    client.Player.MagicPotions--;
                    item = client.Player.Manager.GameData.Items[0xa23];
                }
                else
                {
                    if (con.Inventory[packet.SlotObject.SlotId] == null) return;

                    item = con.Inventory[packet.SlotObject.SlotId];
                    con.Inventory[packet.SlotObject.SlotId] = null;
                }
                entity.UpdateCount++;

                if (item != null)
                {
                    Container container;
                    if (item.Soulbound)
                    {
                        container = new Container(client.Player.Manager, SOUL_BAG, 1000*30, true)
                        {
                            BagOwners = new string[1] { client.Player.AccountId }
                        };
                    }
                    else
                    {
                        container = new Container(client.Player.Manager, NORM_BAG, 1000*30, true);
                    }
                    float bagx = entity.X + (float) ((invRand.NextDouble()*2 - 1)*0.5);
                    float bagy = entity.Y + (float) ((invRand.NextDouble()*2 - 1)*0.5);
                    try
                    {
                        container.Inventory[0] = item;
                        container.Move(bagx, bagy);
                        container.Size = 75;
                        client.Player.Owner.EnterWorld(container);

                        if (entity is Player)
                        {
                            (entity as Player).CalcBoost();
                            (entity as Player).Client.SendPacket(new InvResultPacket
                            {
                                Result = 0
                            });
                            (entity as Player).Client.Save();
                        }

                        if (client.Player.Owner is Vault)
                            if ((client.Player.Owner as Vault).PlayerOwnerName == client.Account.Name)
                                return;
                    }
                    catch (Exception ex)
                    {
                        log.Error(ex);
                        log.InfoFormat(client.Player.Name + " just attempted to dupe.");
                    }
                }
            }, PendingPriority.Networking);

if (client.Player.Owner == null) return;

            if (client.Player.Owner is PetYard)
            {
                client.SendPacket(new InvResultPacket
                {
                    Result = 0
                });
            }

            client.Manager.Logic.AddPendingAction(t =>
            {
                Entity en1 = client.Player.Owner.GetEntity(packet.SlotObject1.ObjectId);
                Entity en2 = client.Player.Owner.GetEntity(packet.SlotObject2.ObjectId);
                IContainer con1 = en1 as IContainer;
                IContainer con2 = en2 as IContainer;

                if (packet.SlotObject1.SlotId == 254 || packet.SlotObject1.SlotId == 255 ||
                    packet.SlotObject2.SlotId == 254 || packet.SlotObject2.SlotId == 255)
                {
                    if (packet.SlotObject2.SlotId == 254)
                        if (client.Player.HealthPotions < 6)
                        {
                            client.Player.HealthPotions++;
                            con1.Inventory[packet.SlotObject1.SlotId] = null;
                        }
                    if (packet.SlotObject2.SlotId == 255)
                        if (client.Player.MagicPotions < 6)
                        {
                            client.Player.MagicPotions++;
                            con1.Inventory[packet.SlotObject1.SlotId] = null;
                        }
                    if (packet.SlotObject1.SlotId == 254)
                        if (client.Player.HealthPotions > 0)
                        {
                            client.Player.HealthPotions--;
                            con2.Inventory[packet.SlotObject2.SlotId] = null;
                        }
                    if (packet.SlotObject1.SlotId == 255)
                        if (client.Player.MagicPotions > 0)
                        {
                            client.Player.MagicPotions--;
                            con2.Inventory[packet.SlotObject1.SlotId] = null;
                        }
                    if (en1 is Player)
                        (en1 as Player).Client.SendPacket(new InvResultPacket {Result = 0});
                    else if (en2 is Player)
                        (en2 as Player).Client.SendPacket(new InvResultPacket {Result = 0});
                    return;
                }
                //TODO: locker
                Item item1 = con1.Inventory[packet.SlotObject1.SlotId];
                Item item2 = con2.Inventory[packet.SlotObject2.SlotId];
                List<ushort> publicbags = new List<ushort>
                {
                    0x0500,
                    0x0506,
                    0x0501
                };

                if (en1.Dist(en2) > 1)
                {
                    if (en1 is Player)
                        (en1 as Player).Client.SendPacket(new InvResultPacket
                        {
                            Result = -1
                        });
                    else if (en2 is Player)
                        (en2 as Player).Client.SendPacket(new InvResultPacket
                        {
                            Result = -1
                        });
                    en1.UpdateCount++;
                    en2.UpdateCount++;
                    return;
                }

                if (!IsValid(item1, item2, con1, con2, packet, client))
                {
                    client.Disconnect();
                    return;
                }

                if (con2 is OneWayContainer)
                {
                    con1.Inventory[packet.SlotObject1.SlotId] = null;
                    con2.Inventory[packet.SlotObject2.SlotId] = null;
                    client.Player.DropBag(item1);
                    en1.UpdateCount++;
                    en2.UpdateCount++;
                    return;
                }
                if (con1 is OneWayContainer)
                {
                    if (con2.Inventory[packet.SlotObject2.SlotId] != null)
                    {
                        (en2 as Player)?.Client.SendPacket(new InvResultPacket {Result = -1});
                        (con1 as OneWayContainer).UpdateCount++;
                        en2.UpdateCount++;
                        return;
                    }

                    using (Database db = new Database())
                    {
                        try
                        {
                            Account acc = db.GetAccount(client.Account.AccountId, Manager.GameData);
                            acc.Gifts.Remove(con1.Inventory[packet.SlotObject1.SlotId].ObjectType);

                            MySqlCommand cmd = db.CreateQuery();
                            cmd.CommandText = @"UPDATE accounts SET gifts=@gifts WHERE id=@accId;";
                            cmd.Parameters.AddWithValue("@accId", acc.AccountId);
                            cmd.Parameters.AddWithValue("@gifts", Utils.GetCommaSepString(acc.Gifts.ToArray()));
                            cmd.ExecuteNonQuery();
                        }
                        catch (Exception ex)
                        {
                            log.Error(ex);
                        }
                    }
                    con1.Inventory[packet.SlotObject1.SlotId] = null;
                    con2.Inventory[packet.SlotObject2.SlotId] = item1;
                    (en2 as Player).CalcBoost();
                    client.Player.SaveToCharacter();
                    client.Save();
                    en1.UpdateCount++;
                    en2.UpdateCount++;
                    (en2 as Player).Client.SendPacket(new InvResultPacket {Result = 0});
                    return;
                }

                if (en1 is Player && en2 is Player & en1.Id != en2.Id)
                {
                    client.Manager.Chat.Announce($"{en1.Name} just tried to steal items from {en2.Name}'s inventory, GTFO YOU GOD DAMN FEGIT!!!!11111oneoneoneeleven");
                    return;
                };

                con1.Inventory[packet.SlotObject1.SlotId] = item2;
                con2.Inventory[packet.SlotObject2.SlotId] = item1;

                if (item2 != null)
                {
                    if (publicbags.Contains(en1.ObjectType) && item2.Soulbound)
                    {
                        client.Player.DropBag(item2);
                        con1.Inventory[packet.SlotObject1.SlotId] = null;
                    }
                }
